package dev.xnaq.gdrivebackup.backup;

import java.nio.file.FileSystems;
import java.nio.file.Path;
import java.nio.file.PathMatcher;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Decides which server files belong in a backup.
 *
 * <p>Default exclusions cover directories that are either regenerated by the
 * server or that must never be uploaded (logs, libraries, credentials, and
 * the backup output directory itself).</p>
 */
public final class BackupPathFilter {
    private static final Set<String> DEFAULT_PREFIXES = Set.of(
            "logs",
            "crash-reports",
            "cache",
            "libraries",
            "versions",
            ".mixin.out",
            "debug",
            "backups",
            "config/gdrivebackup"
    );

    private static final Set<String> DEFAULT_FILE_NAMES = Set.of(
            "session.lock"
    );

    private final Set<Path> excludedRoots;
    private final Set<String> extraPrefixes = new LinkedHashSet<>();
    private final List<PathMatcher> globMatchers = new ArrayList<>();

    public BackupPathFilter(List<? extends String> patterns, Set<Path> excludedRoots) {
        this.excludedRoots = excludedRoots.stream()
                .map(path -> path.toAbsolutePath().normalize())
                .collect(java.util.stream.Collectors.toUnmodifiableSet());

        for (String raw : patterns) {
            if (raw == null || raw.isBlank()) {
                continue;
            }
            String pattern = raw.trim().replace('\\', '/');
            while (pattern.startsWith("/")) {
                pattern = pattern.substring(1);
            }
            if (pattern.endsWith("/")) {
                pattern = pattern.substring(0, pattern.length() - 1);
            }
            if (pattern.isBlank()) {
                continue;
            }
            if (!containsGlob(pattern)) {
                extraPrefixes.add(pattern);
            } else {
                globMatchers.add(FileSystems.getDefault().getPathMatcher("glob:" + pattern));
            }
        }
    }

    public boolean isExcluded(Path absolute, Path relative) {
        Path normalizedAbsolute = absolute.toAbsolutePath().normalize();
        for (Path excludedRoot : excludedRoots) {
            if (normalizedAbsolute.startsWith(excludedRoot)) {
                return true;
            }
        }

        String relativePath = normalize(relative);
        if (relativePath.isEmpty()) {
            return false;
        }

        String fileName = relative.getFileName() == null
                ? relativePath
                : relative.getFileName().toString().toLowerCase(Locale.ROOT);
        if (DEFAULT_FILE_NAMES.contains(fileName)) {
            return true;
        }

        for (String prefix : DEFAULT_PREFIXES) {
            if (matchesPrefix(relativePath, prefix)) {
                return true;
            }
        }
        for (String prefix : extraPrefixes) {
            if (matchesPrefix(relativePath, prefix)) {
                return true;
            }
        }

        Path relativePathObject = Path.of(relativePath);
        for (PathMatcher matcher : globMatchers) {
            if (matcher.matches(relativePathObject)) {
                return true;
            }
        }
        return false;
    }

    private static boolean matchesPrefix(String relativePath, String prefix) {
        return relativePath.equals(prefix) || relativePath.startsWith(prefix + "/");
    }

    private static boolean containsGlob(String pattern) {
        return pattern.indexOf('*') >= 0 || pattern.indexOf('?') >= 0
                || pattern.indexOf('[') >= 0 || pattern.indexOf('{') >= 0;
    }

    private static String normalize(Path path) {
        return path.toString().replace('\\', '/');
    }
}
